function testInputValidation(apiUrl, userId) {
    // Check if apiUrl is a valid string URL
    if (typeof apiUrl !== 'string' || !apiUrl.startsWith('https://')) {
        return false;
    }
    // Check if userId is a valid alphanumeric string
    if (typeof userId !== 'string' || !/^[a-zA-Z0-9]+$/.test(userId)) {
        return false;
    }
    return true;
}

// Example usage:
console.log(testInputValidation('https://example.com/api/user', 'aBc123'));  // Expected output: true
console.log(testInputValidation('https://example.com/api/user', ''));       // Expected output: false
